CREATE TABLE screening_row_registrations(
 id TEXT PRIMARY KEY,store_id TEXT NOT NULL REFERENCES stores(id),project_id TEXT NOT NULL REFERENCES screening_project_versions(id),batch_version_id TEXT NOT NULL REFERENCES screening_batch_versions(id),row_number INTEGER NOT NULL CHECK(row_number BETWEEN 1 AND 500),customer_id TEXT NOT NULL UNIQUE REFERENCES customers(id) DEFERRABLE INITIALLY DEFERRED,link_id TEXT NOT NULL UNIQUE REFERENCES screening_row_link_versions(id) DEFERRABLE INITIALLY DEFERRED,customer_snapshot_json TEXT NOT NULL CHECK(json_valid(customer_snapshot_json)),customer_profile_prefix INTEGER NOT NULL CHECK(customer_profile_prefix>=0),duplicate_refs_json TEXT NOT NULL CHECK(json_valid(duplicate_refs_json)),no_existing_customer INTEGER NOT NULL CHECK(no_existing_customer=1),reviewed_candidates INTEGER NOT NULL CHECK(reviewed_candidates>=0),source TEXT NOT NULL CHECK(source IN('employee','external','guardian_report')),source_note TEXT NOT NULL,review_note TEXT NOT NULL,record_reason TEXT NOT NULL,created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),actor_role TEXT NOT NULL CHECK(actor_role IN('manager','reception')),UNIQUE(batch_version_id,row_number)
);
CREATE TRIGGER screening_registration_source BEFORE INSERT ON screening_row_registrations BEGIN
 SELECT CASE WHEN EXISTS(SELECT 1 FROM customers WHERE id=NEW.customer_id) OR EXISTS(SELECT 1 FROM screening_row_link_versions WHERE id=NEW.link_id) OR EXISTS(SELECT 1 FROM screening_row_link_current WHERE batch_version_id=NEW.batch_version_id AND row_number=NEW.row_number AND action='link') THEN RAISE(ABORT,'screening registration only a new customer and unlinked row') END;
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM screening_batch_current b JOIN screening_project_current p ON p.root_id=b.project_id JOIN users u ON u.id=NEW.created_by LEFT JOIN user_security s ON s.user_id=u.id JOIN users owner ON owner.id=p.owner_id LEFT JOIN user_security os ON os.user_id=owner.id WHERE b.id=NEW.batch_version_id AND b.store_id=NEW.store_id AND p.root_id=NEW.project_id AND p.store_id=NEW.store_id AND p.action='record' AND p.authorization_status='recorded' AND json_array_length(screening_csv_row(b.csv_text,NEW.row_number,b.created_at),'$.errors')=0 AND u.role=NEW.actor_role AND u.store_id=NEW.store_id AND u.active=1 AND coalesce(s.must_change_password,0)=0 AND (u.role='manager' OR u.id=p.owner_id) AND owner.active=1 AND owner.store_id=p.store_id AND owner.role IN('manager','reception','professional') AND coalesce(os.must_change_password,0)=0) THEN RAISE(ABORT,'screening registration current original authorization and create role') END;
 SELECT CASE WHEN NEW.customer_snapshot_json IS NOT screening_customer_data(NEW.customer_snapshot_json,NEW.created_at) OR NEW.customer_profile_prefix IS NOT (SELECT coalesce(max(rowid),0) FROM customer_profile_versions) THEN RAISE(ABORT,'screening registration explicit profile and original prefix') END;
 SELECT CASE WHEN NEW.reviewed_candidates<>json_array_length(NEW.duplicate_refs_json) OR NEW.duplicate_refs_json IS NOT (SELECT json_group_array(json_object('customer_id',id,'version',version)) FROM (SELECT c.id,(SELECT max(version) FROM customer_profile_versions WHERE customer_id=c.id) version FROM customers c WHERE c.store_id=NEW.store_id AND (c.name=json_extract(NEW.customer_snapshot_json,'$.name') OR json_extract(NEW.customer_snapshot_json,'$.phone') IS NOT NULL AND c.phone=json_extract(NEW.customer_snapshot_json,'$.phone')) ORDER BY c.id)) THEN RAISE(ABORT,'screening registration complete original duplicate candidates') END;
END;
CREATE TRIGGER screening_registration_text BEFORE INSERT ON screening_row_registrations WHEN length(trim(NEW.source_note)) NOT BETWEEN 1 AND 500 OR length(NEW.source_note)>500 OR instr(NEW.source_note,char(0))>0 OR length(trim(NEW.review_note)) NOT BETWEEN 1 AND 300 OR length(NEW.review_note)>300 OR instr(NEW.review_note,char(0))>0 OR length(trim(NEW.record_reason)) NOT BETWEEN 1 AND 300 OR length(NEW.record_reason)>300 OR instr(NEW.record_reason,char(0))>0 OR length(NEW.created_at)<>24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.created_at) IS NOT NEW.created_at BEGIN SELECT RAISE(ABORT,'screening registration explicit source and reason');END;
CREATE TRIGGER screening_registration_create AFTER INSERT ON screening_row_registrations BEGIN
 INSERT INTO customers VALUES(NEW.customer_id,NEW.store_id,json_extract(NEW.customer_snapshot_json,'$.name'),json_extract(NEW.customer_snapshot_json,'$.birth_date'),json_extract(NEW.customer_snapshot_json,'$.contact_name'),json_extract(NEW.customer_snapshot_json,'$.phone'),NEW.created_at,NEW.created_by);
 INSERT INTO screening_row_link_versions(id,store_id,project_id,batch_id,batch_version_id,row_number,row_snapshot_json,revision,sequence,action,customer_id,customer_version,project_version_id,project_sequence,batch_sequence,customer_profile_prefix,record_reason,created_at,created_by,actor_role)
 SELECT NEW.link_id,NEW.store_id,NEW.project_id,b.root_id,b.id,NEW.row_number,screening_csv_row(b.csv_text,NEW.row_number,b.created_at),coalesce((SELECT revision+1 FROM screening_row_link_current WHERE batch_version_id=b.id AND row_number=NEW.row_number),1),coalesce((SELECT max(sequence)+1 FROM screening_row_link_versions WHERE store_id=NEW.store_id),1),'link',NEW.customer_id,1,p.id,(SELECT max(sequence) FROM screening_project_versions WHERE store_id=NEW.store_id),(SELECT max(sequence) FROM screening_batch_versions WHERE store_id=NEW.store_id),(SELECT max(rowid) FROM customer_profile_versions),NEW.record_reason,NEW.created_at,NEW.created_by,NEW.actor_role FROM screening_batch_versions b JOIN screening_project_current p ON p.root_id=NEW.project_id WHERE b.id=NEW.batch_version_id;
END;
CREATE TRIGGER screening_registration_no_update BEFORE UPDATE ON screening_row_registrations BEGIN SELECT RAISE(ABORT,'screening registration immutable source');END;
CREATE TRIGGER screening_registration_no_delete BEFORE DELETE ON screening_row_registrations BEGIN SELECT RAISE(ABORT,'screening registration immutable source');END;
